// Put the measurable keyboard relationship before the naming rules.
const distances=[['C','纯一度',0],['D♭','小二度',1],['D','大二度',2],['E♭','小三度',3],['E','大三度',4],['F','纯四度',5],['F♯ / G♭','增四度 / 减五度',6],['G','纯五度',7],['A♭','小六度',8],['A','大六度',9],['B♭','小七度',10],['B','大七度',11],['C↑','纯八度',12]];
const chart=document.createElement('section');chart.className='reading-card distance-card';chart.innerHTML=`<span class="eyebrow">先看图 / 从 C 出发</span><h2>每走过一个相邻琴键，就是一个半音。</h2><p>白键到相邻黑键、黑键到相邻白键，都是 1 半音；没有黑键隔开的 E–F、B–C，也都是 1 半音。点击任意一列，看它距离 C 有多远。</p><div class="distance-scroll"><div class="distance-content"><div class="letter-degree"><span>一度 C</span><span>二度 D</span><span>三度 E</span><span>四度 F</span><span>五度 G</span><span>六度 A</span><span>七度 B</span><span>八度 C</span></div><div class="distance-piano">${[0,2,4,5,7,9,11,12].map((n,i)=>`<button class="distance-key white" data-distance="${n}"><span>${distances[n][0]}</span></button>`).join('')}${[1,3,6,8,10].map(n=>`<button class="distance-key black" data-distance="${n}" style="left:calc(${[0,2,4,5,7,9,11,12].filter(x=>x<n).length*12.5}% - 3.5%)"><span>${distances[n][0]}</span></button>`).join('')}</div><div class="distance-table"><span>距 C 的半音数</span>${distances.map(x=>`<button data-distance="${x[2]}"><b>${x[2]}</b><span>${x[0]}</span><small>${x[1]}</small></button>`).join('')}</div></div></div><p class="swipe-hint">窄屏可左右滑动查看整张图 ↔</p><div class="distance-reading" id="distanceReading" aria-live="polite"></div><div class="counting-steps" id="countingSteps"></div><button class="primary" id="distanceHear">▶ 听 C 和选中的音</button><p class="distance-footnote">上方“一～八度”按自然音名字母计数；下方“0～12”按相邻键的步数计数。黑键可有不同写法，表中列出常见名称；完整名称仍须结合音名拼写判断。</p>`;
$('#panel-1 .topic-heading').after(chart);$('#panel-1 .topic-heading p').textContent='先把 0～12 个半音和音程名称对应起来，再学习它们为什么这样命名。';
let distanceSelected=4;
function distanceRender(n){distanceSelected=n;const x=distances[n];$$('[data-distance]').forEach(b=>{b.classList.toggle('chosen',+b.dataset.distance===n);b.classList.toggle('origin',+b.dataset.distance===0);b.setAttribute('aria-pressed',+b.dataset.distance===n)});$('#distanceReading').innerHTML=`<div><small>当前观察</small><strong>C → ${x[0]}</strong></div><div><small>距离：数走了几步</small><strong>${n} 个半音</strong></div><div><small>音程名称</small><strong>${x[1]}</strong></div>`;$('#countingSteps').innerHTML=n===4?'<strong>以 C → E 为例</strong><p>数距离：C → C♯ → D → D♯ → E，走了 <b>4 步</b>，所以是 4 半音。</p><p>数音名：C、D、E，连起点和终点共 <b>3 个字母</b>，所以是三度。三度中，4 半音叫<b>大三度</b>。</p><p>中间虽有两个黑键、一个白键，但“中间有 3 个键”不是三度的定义。</p>':`<strong>先分清两个刻度</strong><p>C 到 ${x[0]} 的键盘距离是 ${n} 半音。音程是 ${x[1]}；若改变等音拼写，名称可能随字母跨度改变。</p>`;}
chart.onclick=e=>{const b=e.target.closest('[data-distance]');if(b)distanceRender(+b.dataset.distance)};$('#distanceHear').onclick=()=>sound([60,60+distanceSelected],.65);distanceRender(4);
// Two simultaneous registers: accompaniment below, melody above.
$('#pianoPanel').classList.add('two-registers');$('#pianoPanel .piano-toolbar small').textContent='伴奏 + 旋律 · 两个音区可同时演奏';
const lowKeyboardCodes=['Digit1','Digit2','Digit3','Digit4','Digit5','Digit6','Digit7','Digit8','Digit9','Digit0'];const lowOffsets=[-12,-10,-8,-7,-5,-3,-1,0,2,4];
function registerKeys(start,count,hints){const whiteCount=Array.from({length:count},(_,i)=>start+i).filter(n=>![1,3,6,8,10].includes((n+120)%12)).length;let whites=0;return Array.from({length:count},(_,i)=>{const offset=start+i,m=(octave+1)*12+offset,pc=m%12,black=[1,3,6,8,10].includes(pc),pos=whites;if(!black)whites++;const name=roots.find(r=>r[1]===pc)[0]+(Math.floor(m/12)-1);return `<button class="live-key ${black?'black':'white'}" data-offset="${offset}" style="${black?'left:calc('+pos/whiteCount*100+'% - 2%)':'width:'+100/whiteCount+'%'}" aria-label="${name}"><span>${name}</span><kbd>${hints(offset)||'·'}</kbd></button>`}).join('')}
pianoKeys=function(){const melodyHints=n=>keyHints[n];const bassHints=n=>{const i=lowOffsets.indexOf(n);return i<0?'':String((i+1)%10)};$('#liveKeyboard').innerHTML=`<section class="register"><div class="register-label"><strong>伴奏音区</strong><span>C${octave-1}–C${octave+1} · 数字 1～0 对应标注白键</span></div><div class="register-scroll"><div class="register-keys">${registerKeys(-12,25,bassHints)}</div></div></section><section class="register"><div class="register-label"><strong>旋律音区</strong><span>C${octave}–C${octave+2} · 白键 A S D F G H J K L ;</span></div><div class="register-scroll"><div class="register-keys">${registerKeys(0,25,melodyHints)}</div></div></section>`;$('#octLabel').textContent=`主音区 C${octave}`;};
$('#pianoPanel .piano-help').innerHTML='<span>旋律黑键 W E T Y U O P；未标字母的键可用触屏或鼠标弹。</span><span>Z / X 移动两组音区 · 多指可跨两个音区同时按键</span>';
document.addEventListener('keydown',e=>{if($('#pianoPanel').hidden||e.repeat||e.isComposing||e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,select,textarea,[contenteditable=true]'))return;const i=lowKeyboardCodes.indexOf(e.code);if(i>=0){e.preventDefault();noteOn(e.code,lowOffsets[i])}});
const backing=[{name:'Cmaj7',notes:[-12,-8,-5,-1]},{name:'Am7',notes:[-15,-12,-8,-5]},{name:'Dm7',notes:[-10,-7,-3,0]},{name:'G7',notes:[-17,-13,-10,-7]}];
// Voice the two lower chords up an octave so every shown note fits the accompaniment register.
backing[1].notes=[-3,0,4,7];backing[3].notes=[-5,-1,2,5];
const accompaniment=document.createElement('div');accompaniment.className='accompaniment';accompaniment.innerHTML=`<div class="backing-head"><strong>四音和弦伴奏</strong><span>按住按钮试听；旋律区仍可自由弹奏</span></div><div class="backing-pads">${backing.map((c,i)=>`<button data-backing="${i}">${c.name}<small>${c.notes.map(n=>roots.find(r=>r[1]===(n+120)%12)[0]).join(' · ')}</small></button>`).join('')}</div><div class="demo-controls"><button id="songDemo">▶ 原创小练习 · 伴奏与旋律</button><button id="stopSong" disabled>■ 停止</button><span id="songStatus" role="status">C 大调 · 4 小节 · 80 BPM · 旋律 C4–D5（九度）</span></div>`;$('#liveKeyboard').before(accompaniment);
const padIds=new Map();accompaniment.onpointerdown=e=>{const b=e.target.closest('[data-backing]');if(!b)return;e.preventDefault();b.setPointerCapture(e.pointerId);const ids=backing[+b.dataset.backing].notes.map((n,i)=>{const id='pad-'+e.pointerId+'-'+i;noteOn(id,n);return id});padIds.set(e.pointerId,ids);b.classList.add('pressed')};['pointerup','pointercancel','lostpointercapture'].forEach(t=>accompaniment.addEventListener(t,e=>{(padIds.get(e.pointerId)||[]).forEach(noteOff);padIds.delete(e.pointerId);e.target.closest('[data-backing]')?.classList.remove('pressed')}));
$$('[data-backing]').forEach(b=>{b.onkeydown=e=>{if((e.code==='Space'||e.code==='Enter')&&!e.repeat){e.preventDefault();backing[+b.dataset.backing].notes.forEach((n,i)=>noteOn('pad-key-'+b.dataset.backing+'-'+i,n));b.classList.add('pressed')}};b.onkeyup=e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();backing[+b.dataset.backing].notes.forEach((_,i)=>noteOff('pad-key-'+b.dataset.backing+'-'+i));b.classList.remove('pressed')}};b.onblur=()=>{backing[+b.dataset.backing].notes.forEach((_,i)=>noteOff('pad-key-'+b.dataset.backing+'-'+i));b.classList.remove('pressed')}});
let songTimers=[],songRunning=false;
function stopSong(){songTimers.forEach(clearTimeout);songTimers=[];[...held].filter(id=>id.startsWith('song-')).forEach(noteOff);songRunning=false;$('#songDemo').disabled=false;$('#stopSong').disabled=true;$('#songStatus').textContent='已停止 · 可自由弹奏或重新播放';$$('[data-backing]').forEach(b=>b.classList.remove('playing'))}
function later(fn,ms){songTimers.push(setTimeout(fn,ms))}
$('#songDemo').onclick=async()=>{stopSong();await audio();songRunning=true;$('#songDemo').disabled=true;$('#stopSong').disabled=false;const beat=750,base=octave;
 const melody=[[0,4,7,12],[9,7,4,0],[2,5,9,14],[11,7,2,0]];
 backing.forEach((c,bar)=>{later(()=>{if(!songRunning)return;$('#songStatus').textContent=`第 ${bar+1} / 4 小节 · ${c.name} · 旋律与四音伴奏同时播放`;$$('[data-backing]').forEach(b=>b.classList.toggle('playing',+b.dataset.backing===bar));c.notes.forEach((n,i)=>noteOn('song-bass-'+bar+'-'+i,n));},bar*4*beat);later(()=>c.notes.forEach((_,i)=>noteOff('song-bass-'+bar+'-'+i)),(bar*4+3.8)*beat);melody[bar].forEach((n,i)=>{const id='song-melody-'+bar+'-'+i;later(()=>noteOn(id,n),(bar*4+i)*beat);later(()=>noteOff(id),(bar*4+i+.85)*beat)})});later(()=>{stopSong();$('#songStatus').textContent=`播放完毕 · 原创示范 · 旋律 C${base}–D${base+1}（九度）`},16*beat+100)};
$('#stopSong').onclick=stopSong;const previousClose=openPiano;openPiano=function(open){if(!open)stopSong();previousClose(open)};const previousOctave=changeOctave;changeOctave=function(d){stopSong();previousOctave(d)};window.addEventListener('blur',stopSong);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSong()});
// Prevent a held chord button from losing its release when focus changes.
window.addEventListener('blur',()=>{$$('[data-backing]').forEach(b=>b.classList.remove('pressed'));padIds.clear()});
