chords.push(
{id:'9',name:'属九和弦',suffix:'9',formula:'1 · 3 · 5 · ♭7 · 9',intervals:[0,4,7,10,14],degrees:[0,2,4,6,8],labels:['根音','大三度','纯五度','小七度','大九度'],group:'extended',text:'数字 9 通常隐含属七和弦：大三和弦 + 小七度 + 大九度。属九和弦含小七度；add9 和弦不自动包含七音。这些构成规则适用于任意根音。'},
{id:'maj9',name:'大九和弦',suffix:'maj9',formula:'1 · 3 · 5 · 7 · 9',intervals:[0,4,7,11,14],degrees:[0,2,4,6,8],labels:['根音','大三度','纯五度','大七度','大九度'],group:'extended',text:'在大七和弦上加大九度。maj 指大七度性质，不是说“九度比属九和弦更大”；两者的九音相同，七音不同。'},
{id:'m9',name:'小九和弦',suffix:'m9',formula:'1 · ♭3 · 5 · ♭7 · 9',intervals:[0,3,7,10,14],degrees:[0,2,4,6,8],labels:['根音','小三度','纯五度','小七度','大九度'],group:'extended',text:'小七和弦加大九度。m 指小三和弦基础，并不表示把九音降低。它的九音相对根音仍是大九度。'},
{id:'add9',name:'加九和弦',suffix:'add9',formula:'1 · 3 · 5 · 9',intervals:[0,4,7,14],degrees:[0,2,4,8],labels:['根音','大三度','纯五度','大九度'],group:'added',text:'add 表示额外加入指定音，不自动补七音。它与属九和弦的关键区别：这里不含小七度。'},
{id:'madd9',name:'小加九和弦',suffix:'m(add9)',formula:'1 · ♭3 · 5 · 9',intervals:[0,3,7,14],degrees:[0,2,4,8],labels:['根音','小三度','纯五度','大九度'],group:'added',text:'在小三和弦上加入大九度，不含七音。三音为小三度，九音仍为大九度。'},
{id:'6',name:'大六和弦',suffix:'6',formula:'1 · 3 · 5 · 6',intervals:[0,4,7,9],degrees:[0,2,4,5],labels:['根音','大三度','纯五度','大六度'],group:'added',text:'流行或爵士和弦符号中，后缀 6 是在大三和弦上加大六度，不自动包含七音。六音距根音为 9 半音；古典数字低音中的“六和弦”则可能指三和弦第一转位，要看记谱体系。'},
{id:'m6',name:'小六和弦',suffix:'m6',formula:'1 · ♭3 · 5 · 6',intervals:[0,3,7,9],degrees:[0,2,4,5],labels:['根音','小三度','纯五度','大六度'],group:'added',text:'小三和弦加大六度。六音距根音仍为大六度（9 半音），不是小六度；后缀 m 主要描述三和弦性质。'},
{id:'69',name:'六九和弦',suffix:'6/9',formula:'1 · 3 · 5 · 6 · 9',intervals:[0,4,7,9,14],degrees:[0,2,4,5,8],labels:['根音','大三度','纯五度','大六度','大九度'],group:'added',text:'三和弦同时加入大六度、大九度，通常不含七音。六音、九音分别距根音 9、14 半音。这里的斜线连接两个扩展音数字，不是在指定低音。'},
{id:'11',name:'属十一和弦',suffix:'11',formula:'1 · 3 · 5 · ♭7 · 9 · 11',intervals:[0,4,7,10,14,17],degrees:[0,2,4,6,8,10],labels:['根音','大三度','纯五度','小七度','大九度','纯十一度'],group:'extended',text:'理论完整叠置包含属七、九音和十一音。本实验展示完整结构；实际配器常省音，尤其会处理三音与十一音的紧张关系。不要把 11 直接当作只有三音被替换的 sus4。'},
{id:'13',name:'属十三和弦',suffix:'13',formula:'1 · 3 · 5 · ♭7 · 9 · 13（省 11）',intervals:[0,4,7,10,14,21],degrees:[0,2,4,6,8,12],labels:['根音','大三度','纯五度','小七度','大九度','大十三度'],group:'extended',text:'属十三和弦包含小七度与大十三度。这里展示保留九音、省略十一音的常见组织方式；理论逐三度叠置还有十一音。实际演奏常省五音等，符号不要求所有音同时出现。'});
const extIntro=document.createElement('section');extIntro.className='reading-card';extIntro.innerHTML=`<span class="eyebrow">读懂谱上的数字</span><h2>9、add9、6，到底加了什么？</h2><p>先读三和弦性质，再读七音，最后读扩展音。以下讨论的是和弦类型，适用于任意根音。所有音程均相对根音；进入模拟器后，可自行选择根音查看具体组成音。</p><div class="reading-grid"><div class="rule-block"><h3>九和弦与 add9 和弦</h3><p><strong>九和弦（属九，9）</strong>：1 · 3 · 5 · ♭7 · 9<br>根音 + 大三度 + 纯五度 + 小七度 + 大九度。</p><p><strong>add9 和弦（加九）</strong>：1 · 3 · 5 · 9<br>三和弦加大九度，<strong>不自动加七音</strong>。</p><button class="subtle" data-chord-example="9">探索九和弦 ↗</button><button class="subtle" data-chord-example="add9">探索 add9 和弦 ↗</button></div><div class="rule-block"><h3>六和弦与六九和弦</h3><p><strong>六和弦（6）</strong>：1 · 3 · 5 · 6<br>根音 + 大三度 + 纯五度 + 大六度，通常不含七音。</p><p><strong>六九和弦（6/9）</strong>：1 · 3 · 5 · 6 · 9<br>根音 + 大三度 + 纯五度 + 大六度 + 大九度，通常不含七音。</p><button class="subtle" data-chord-example="6">探索六和弦 ↗</button><button class="subtle" data-chord-example="69">探索六九和弦 ↗</button></div></div><h3>九、十一、十三，来自八度以外</h3><p>大九度 = 大二度 + 八度 = 14 半音；纯十一度 = 纯四度 + 八度 = 17 半音；大十三度 = 大六度 + 八度 = 21 半音。同一音级放在不同八度，实际排列与听感会变化。add9 与 sus2 也不同：add9 保留三音，sus2 用二音替代三音。</p><details><summary>数字与斜线：C/E、6/9、6/5 是一回事吗？</summary><p><strong>C/E</strong>：C 大三和弦，以 E 为最低音；斜线后是音名。<strong>C6/9</strong>：C 和弦加入六音与九音；斜线后仍是数字。古典数字低音中的 <strong>6/5（有时上下排列）</strong> 则常用于七和弦第一转位，描述低音上方的音程。它们属于不同记法，不能只看数字猜构成。</p><p>单独写出的“5、6”也可能是简谱级数或其他标记，必须结合完整谱例判断。</p></details><details><summary>为什么谱写了 13，演奏时却未必按七个音？</summary><p>和弦符号描述和声身份，具体声部排列可以省略、重复或换八度。钢琴常优先保留三音、七音与所需色彩音；有贝斯时根音也可能交给贝斯。这里的模拟器展示一套明确写出的音集，不代表唯一指法。</p></details>`;
